-- Proposed PostgreSQL/PostGIS schema; not required by the dependency-free demo.
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE users (user_id uuid PRIMARY KEY, name text NOT NULL, phone text, role text NOT NULL CHECK(role IN ('citizen','official','admin')));
CREATE TABLE disaster_events (event_id uuid PRIMARY KEY, disaster_type text NOT NULL, severity text NOT NULL, affected_area geometry(MultiPolygon,4326), start_time timestamptz NOT NULL, status text NOT NULL);
CREATE TABLE nodes (node_id bigint PRIMARY KEY, location geometry(Point,4326) NOT NULL);
CREATE TABLE shelters (shelter_id uuid PRIMARY KEY, name text NOT NULL, latitude double precision CHECK(latitude BETWEEN -90 AND 90), longitude double precision CHECK(longitude BETWEEN -180 AND 180), address text, capacity integer CHECK(capacity>=0), available_capacity integer CHECK(available_capacity>=0 AND available_capacity<=capacity), status text CHECK(status IN ('OPEN','CLOSED','FULL')), medical_facility boolean, food_available boolean, water_available boolean, toilets boolean, accessible boolean, contact text, node_id bigint REFERENCES nodes, version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roads (road_id bigint PRIMARY KEY, start_node bigint REFERENCES nodes, end_node bigint REFERENCES nodes, distance double precision NOT NULL CHECK(distance>0), road_status text CHECK(road_status IN ('OPEN','BLOCKED','UNKNOWN')), risk_level double precision CHECK(risk_level BETWEEN 0 AND 1), accessible boolean, one_way boolean, geometry geometry(LineString,4326), version bigint NOT NULL DEFAULT 1);
CREATE TABLE hazards (hazard_id uuid PRIMARY KEY, event_id uuid REFERENCES disaster_events, hazard_type text NOT NULL, latitude double precision, longitude double precision, affected_area geometry(MultiPolygon,4326), severity text NOT NULL, status text NOT NULL, source text NOT NULL, observed_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1);
CREATE TABLE emergency_facilities (facility_id uuid PRIMARY KEY, name text NOT NULL, type text NOT NULL, latitude double precision, longitude double precision, contact text, location geometry(Point,4326));
CREATE TABLE alerts (alert_id uuid PRIMARY KEY, event_id uuid REFERENCES disaster_events, message text NOT NULL, created_by uuid REFERENCES users, expires_at timestamptz);
CREATE TABLE audit_log (audit_id bigserial PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, record_type text NOT NULL, record_id text NOT NULL, previous_data jsonb, new_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sync_changes (revision bigserial PRIMARY KEY, region_id text NOT NULL, record_type text NOT NULL, record_id text NOT NULL, operation text CHECK(operation IN ('UPSERT','DELETE')), payload jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX roads_geometry ON roads USING gist(geometry);
CREATE INDEX hazard_area ON hazards USING gist(affected_area);
CREATE INDEX facility_location ON emergency_facilities USING gist(location);
-- Working sample data is generated by demo/web/engine.js:scenario().
-- It includes 25 nodes, 40 roads, 3 shelters, 1 hazard and 1 medical facility.
